//! Actual App reporting owns only its own current validation message.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn control_custom_validity_actual_app_report_edit_clear_paint_layout_links_and_unrelated_errors(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-control-custom-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><input id=field name=q><button id=go name=go type=button>Check custom</button><input id=neighbor value=Neighbor><a id=stable href=#target>Go</a><div id=paint></div><div id=target></div><script>var x=document.getElementById('field'),round=0,events=0;x.addEventListener('invalid',function(e){if(!e.isTrusted||e.target!==x)throw 'native invalid';events++;});document.getElementById('go').onclick=function(){if(round===0){x.setCustomValidity('Choose a different value.');if(x.validationMessage!=='Choose a different value.'||x.reportValidity()!==false||events!==1)throw 'custom report';document.title='Custom invalid';}else if(round===1){if(x.value!=='A😀Z'||x.checkValidity()!==false||events!==2||x.validationMessage!=='Choose a different value.')throw 'editing retains custom error';x.setCustomValidity('');if(!x.reportValidity()||x.validationMessage!=='')throw 'custom clear';document.getElementById('paint').className='done';document.title='Custom valid';}else{if(!x.reportValidity())throw 'valid read';document.title='Unrelated retained';}round++;};</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let field=node(&app,"field");let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let before=app.draw();click(&mut app,go);assert_eq!(app.document.title,"Custom invalid");assert!(app.failed);assert_eq!(app.status,"Choose a different value.");assert!(matches!(app.focus,Focus::Control(n)if n==field));for ch in ['A','😀','Z']{app.text_input(ch);}click(&mut app,go);assert_eq!(app.document.title,"Custom valid");assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert!(app.status.is_empty());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let r=app.page.controls.iter().find(|r|r.node==field).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));app.error("Unrelated native error.".into());click(&mut app,go);assert_eq!(app.document.title,"Unrelated retained");assert_eq!(app.status,"Unrelated native error.");assert!(app.failed);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());
}
#[test]
fn control_custom_validity_actual_app_native_submit_uses_custom_message_and_recovers(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-control-custom-submit-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><form id=form><input id=field name=q value=Ready><button id=go name=go>Submit</button></form><script>var x=document.getElementById('field'),round=0,invalid=0;x.setCustomValidity('Native submission blocked.');x.addEventListener('invalid',function(e){if(!e.isTrusted)throw 'native event';invalid++;document.title='Blocked custom';});document.getElementById('go').onclick=function(){if(round++){x.setCustomValidity('');if(!x.reportValidity())throw 'clear native report';}};document.getElementById('form').addEventListener('submit',function(e){e.preventDefault();if(invalid!==1||!e.isTrusted)throw 'submission recovery';document.title='Recovered submit';});</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let field=node(&app,"field");let go=node(&app,"go");let location=app.location.clone();click(&mut app,go);assert_eq!(app.document.title,"Blocked custom");assert_eq!(app.status,"Native submission blocked.");assert!(app.failed);assert!(matches!(app.focus,Focus::Control(n)if n==field));click(&mut app,go);assert_eq!(app.document.title,"Recovered submit");assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert!(app.status.is_empty());assert_eq!(app.location,location);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());
}
